INSERT INTO zoho_import.notes ("note_record_id", "person_type", "person_record_id", "person_name", "note_title", "note_content", "note_owner", "created_by", "created_time", "modified_time") VALUES
  ('zcrm_1579374000023615013', 'contact', 'zcrm_1579374000015937219', 'Abigail McMurray', NULL, 'called for birth control-she is going to submit a drug form. - KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-18 10:01:23', '2018-09-18 10:01:23'),
  ('zcrm_1579374000023599023', 'contact', 'zcrm_1579374000023592190', 'Irene Evans', NULL, 'Member Only $2500 IUA ReDirect 50-59', 'Patti Baron', 'Patti Baron', '2018-09-18 09:18:02', '2018-09-18 09:18:02'),
  ('zcrm_1579374000023615008', 'contact', 'zcrm_1579374000018819148', 'Justin St Germain', NULL, 'Justin called in because his wife just found out that she was pregnant.  He was confused and did not know which steps to take.  I told him to call Sedera- I e-mailed him their number as we discussed and a welcome call scheduler as well.- KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-18 09:15:27', '2018-09-18 09:15:27'),
  ('zcrm_1579374000023618003', 'contact', 'zcrm_1579374000011447500', 'Clove Berger', NULL, 'Left detailed message on voicemail. Let her know if she has any questions or concerns to contact us back. Vanessa Orozco', 'Vanessa Orozco', 'Vanessa Orozco', '2018-09-18 09:06:52', '2018-09-18 09:08:34'),
  ('zcrm_1579374000023615003', 'contact', 'zcrm_1579374000011521372', 'Monica Gerhardstein', NULL, 'Monica called in panicked because she was receiving calls saying that her insurance was cancelled- I told her that I didn''t see any evidence of it on this end, I let her check with Patti  to make sure I was correct.   Patti explained that YES she CAN go to any doctor for injury/illness and that she needed to check the network to make sure when using her ASI card. I helped the client establish the fact that her Dr was not in network but that her OBGYN was.   I gave her all of the options that she could do- go to her gp, pay out of pocket ( I told her how to present herself) submit the bill herself or......nominate the dr and wait to see if she is in network.   THEN she said she had labwork done ALREADY last week- and that she would just cancell the appointment.  I told her that anything out of network would be covered but only up to %130 medicare allowable - and that doesn''t always cover the entire cost.  She told me she would cancel our insurance in a few months when there is open enrollment with obama-care and that she will just go then. - KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-18 08:58:14', '2018-09-18 08:58:14'),
  ('zcrm_1579374000023599018', 'contact', 'zcrm_1579374000023592136', 'Raymond Ellason', NULL, 'Member &amp; Fam $1500 IUA PSD 60-64', 'Patti Baron', 'Patti Baron', '2018-09-18 08:31:17', '2018-09-18 08:31:17'),
  ('zcrm_1579374000023599013', 'contact', 'zcrm_1579374000001445005', 'Sheryl Marinone', NULL, 'Member called in and told me that she cancelled w/LHS I will refund Sept.', 'Patti Baron', 'Patti Baron', '2018-09-18 07:35:37', '2018-09-18 07:35:37'),
  ('zcrm_1579374000023599008', 'contact', 'zcrm_1579374000011740129', 'Julia (Wieck) Hardy', NULL, 'Emp &amp; Fam $1000 IUA', 'Patti Baron', 'Patti Baron', '2018-09-18 07:06:37', '2018-09-18 07:06:37'),
  ('zcrm_1579374000023599003', 'contact', 'zcrm_1579374000011740129', 'Julia (Wieck) Hardy', NULL, 'Member adding son effective 10/1/18', 'Patti Baron', 'Patti Baron', '2018-09-18 07:05:58', '2018-09-18 07:05:58'),
  ('zcrm_1579374000023547023', 'contact', 'zcrm_1579374000011521683', 'Scott Hershman', NULL, 'He called for assistance finding a GP for an annual.  Did a search for him then e-mailed it to him.- KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-17 13:07:44', '2018-09-17 13:07:44'),
  ('zcrm_1579374000023563003', 'contact', 'zcrm_1579374000009604129', 'Lori Frisbie', NULL, 'Call from Lori, she found a lump and biopsy (9/11/18) shows it is cancer.  Just got the results today. It is the most treatable and most common.
Being referred to breast specialist at Dignity.
She is really scared about how well this program will pay for the cancer and also really concerned that she NOT get cancelled because of not having a referral. I instructed her to call the Concierge for direction on using 2nd MD and how to have bills handled, submitted, pre-authorized if needed, etc.', 'Jane Kassel', 'Jane Kassel', '2018-09-17 12:54:20', '2018-09-17 12:54:20'),
  ('zcrm_1579374000023547018', 'contact', 'zcrm_1579374000017243220', 'Cynthia Pittman', NULL, 'On Sunday,  Michael was taken to the ER and hospitalized for kidney stones, Cynthia wondered if it would be considered as a pre-existing condition because this past May, he was hospitalized for the same condition.   After speaking with John I called Cynthia back to tell her that yes, it most likely will be handled as pre-existing BUT she should call Sedera anyway - let them know what is going on and ask if there would be anyway that they could help- as in negotiation - KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-17 12:39:42', '2018-09-17 12:39:42'),
  ('zcrm_1579374000023547013', 'contact', 'zcrm_1579374000012578137', 'Rachel Fisher Ingraham', NULL, 'I gave all of ASI''s contact info to Rachel because she wanted to know what to do with the pap smear bill that she got in the mail.- KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-17 12:19:20', '2018-09-17 12:19:20'),
  ('zcrm_1579374000023547008', 'contact', 'zcrm_1579374000004971047', 'Jeff Myers', NULL, 'called to be reminded of where her preventative care e-mail was.- KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-17 12:16:50', '2018-09-17 12:16:50'),
  ('zcrm_1579374000023547003', 'contact', 'zcrm_1579374000021919141', 'Damien Petta', NULL, 'Damien called in with a question about STI testing covered by his MEC plan, he thought that he would have to find a doctor in network, I told him that if he was dealing with symptoms and discomfort that he could go wherever he wanted to see a doctor and get treatment and present himself as a self-paying patient. He thanked me for clarifying, I asked if he needed help finding a doctor in the area, and he told me not to worry that he had already picked out a few urgent cares near by.- KC', 'Kelly Frederickson', 'Kelly Frederickson', '2018-09-17 12:01:44', '2018-09-17 12:01:44'),
  ('zcrm_1579374000023542003', 'contact', 'zcrm_1579374000011659967', 'Shawn Mynar', NULL, 'Left detailed message on voicemail. Sent email to book online the 15 minute welcome call. Vanessa Orozco', 'Vanessa Orozco', 'Vanessa Orozco', '2018-09-17 11:22:07', '2018-09-17 11:22:07'),
  ('zcrm_1579374000023527008', 'contact', 'zcrm_1579374000013233082', 'Daniel Wisdom', NULL, 'Welcome call complete. Member checking if he has his ASI card and MPower life code and said to get back to us. Vanessa Orozco', 'Vanessa Orozco', 'Vanessa Orozco', '2018-09-17 10:56:13', '2018-09-17 10:56:13'),
